import { createPlayerError } from "./errors.js";
import type { PlayerEvents } from "./types.js";

type Emit = <K extends keyof PlayerEvents>(type: K, detail: PlayerEvents[K]) => void;

/** Returns the end of the last buffered range, or 0 when nothing is buffered. */
export function bufferedEnd(media: HTMLMediaElement): number {
  const ranges = media.buffered;

  if (ranges.length === 0) {
    return 0;
  }

  const end = ranges.end(ranges.length - 1);
  return Number.isFinite(end) ? end : 0;
}

/** Returns a finite duration or 0 for live/unknown streams. */
export function safeDuration(media: HTMLMediaElement): number {
  return Number.isFinite(media.duration) ? media.duration : 0;
}

/** True when the media has no finite duration. */
export function isLiveMedia(media: HTMLMediaElement): boolean {
  return !Number.isFinite(media.duration);
}

/**
 * Bridges native media-element events into the player event bus.
 *
 * Returns an unsubscribe function that detaches every listener.
 */
export function bindMediaElement(media: HTMLMediaElement, emit: Emit): () => void {
  const controller = new AbortController();
  const { signal } = controller;

  const listen = (type: string, listener: EventListener): void => {
    media.addEventListener(type, listener, { signal });
  };

  listen("play", () => emit("play", undefined));
  listen("playing", () => emit("playing", undefined));
  listen("pause", () => emit("pause", undefined));
  listen("waiting", () => emit("waiting", undefined));
  listen("canplay", () => emit("canplay", undefined));
  listen("ended", () => emit("ended", undefined));

  listen("timeupdate", () => {
    emit("timeupdate", {
      currentTime: media.currentTime,
      duration: safeDuration(media),
      buffered: bufferedEnd(media),
    });
  });

  listen("progress", () => emit("progress", { buffered: bufferedEnd(media) }));

  listen("durationchange", () => {
    emit("durationchange", {
      duration: safeDuration(media),
      live: isLiveMedia(media),
    });
  });

  listen("loadedmetadata", () => {
    const video = media instanceof HTMLVideoElement ? media : null;

    emit("loadedmetadata", {
      duration: safeDuration(media),
      width: video?.videoWidth ?? 0,
      height: video?.videoHeight ?? 0,
      live: isLiveMedia(media),
    });
  });

  listen("seeking", () => emit("seeking", { currentTime: media.currentTime }));
  listen("seeked", () => emit("seeked", { currentTime: media.currentTime }));

  listen("volumechange", () => {
    emit("volumechange", { volume: media.volume, muted: media.muted });
  });

  listen("ratechange", () => emit("ratechange", { playbackRate: media.playbackRate }));

  listen("error", () => {
    const mediaError = media.error;
    const error = createPlayerError(mediaError?.message ?? "The media could not be played.", {
      code: "media-error",
      ...(mediaError == null ? {} : { cause: mediaError, details: { code: mediaError.code } }),
    });

    emit("error", { error });
  });

  listen("enterpictureinpicture", () => emit("pictureinpicturechange", { pictureInPicture: true }));
  listen("leavepictureinpicture", () =>
    emit("pictureinpicturechange", { pictureInPicture: false }),
  );

  return () => controller.abort();
}

/** Resolves when metadata is available, or rejects on media error. */
export function waitForMetadata(media: HTMLMediaElement): Promise<void> {
  if (media.readyState >= HTMLMediaElement.HAVE_METADATA) {
    return Promise.resolve();
  }

  return new Promise<void>((resolve, reject) => {
    const cleanup = (): void => {
      media.removeEventListener("loadedmetadata", onLoaded);
      media.removeEventListener("error", onError);
    };

    const onLoaded = (): void => {
      cleanup();
      resolve();
    };

    const onError = (): void => {
      cleanup();
      reject(
        createPlayerError(media.error?.message ?? "The media could not be loaded.", {
          code: "media-error",
          ...(media.error == null ? {} : { cause: media.error }),
        }),
      );
    };

    media.addEventListener("loadedmetadata", onLoaded, { once: true });
    media.addEventListener("error", onError, { once: true });

    // A cached source can become ready between the first check and listener
    // attachment; re-check after attaching to avoid missing the event.
    if (media.readyState >= HTMLMediaElement.HAVE_METADATA) {
      cleanup();
      resolve();
    }
  });
}
